UPDATE lessons SET title='Year 4, Week 14, Lesson 2: Creating a healthy food advertisement', data=json_patch(data,'{"child_mission":"Creating a healthy food advertisement can persuade positively with honest claims, real food photos/drawings and no body-shaming messages.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same idea to a new game or situation, then compare two choices for safety and inclusion.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nRewrite a shaming slogan into an honest, kind one.\n\nFEEDBACK\nAny rewrite without body insults and with a fair claim.\n\nWATCH FOR\nAds that mock bodies are not healthy messaging.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nCreate one honest food ad (poster/script). Peer-check for honesty and kindness.\n\nWrite a short reflection naming one choice you changed and why. Any movement is optional, adult-supervised and can be done in a gentler way or described instead.","interactive_activities":null,"learning_area":"PDHPE","learning_intention":"Creating a healthy food advertisement can persuade positively with honest claims, real food photos/drawings and no body-shaming messages.","lesson_number":2,"lesson_role":"Practise and apply","materials":["Paper or typed answer space","Pencil","Clear, safe movement space with an adult nearby for any physical activity","Optional: soft ball, cushion or water bottle"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["PH2-IHW-01"],"parent_notes":"Parent: Marking guidance for the independent task: Create one honest food ad (poster/script). Peer-check for honesty and kindness. Accept equivalent original responses that show the same s